                            .reserve_array::<(usize, u64)>(&function, 1, "sticky id prime")
                            .unwrap();
                        assert!(
                            current
                                .id_with_receiving(
                                    &function,
                                    vec![(roots[0], 1)],
                                    &mut budget,
                                    &mut receiving
                                )
                                .unwrap()
                                .is_some()
                        );
