                    drop(current);
                    drop(receiving);
                    drop(fresh);
                    drop(budget);
                    drop(foreign_budget);
                });
                // A foreign nested ledger selects sticky refusal on its held
                // outer owner, while the nested payer itself is never queried.
                assert_eq!(refused, kind == 2);
                assert!(first.is_none() || kind == 2);
            });
            assert!(
